	@Test
	void observesChangesToCustomDatatypeIrisBetweenRows() throws Exception {
		class MutableDatatypeIRI extends SimpleIRI {
			MutableDatatypeIRI(String iri) {
				super(iri);
			}

			void changeTo(String iri) {
				setIRIString(iri);
			}
		}
		String firstNamespace = "http://example.org/first/";
		String secondNamespace = "http://example.org/second/";
		MutableDatatypeIRI datatype = new MutableDatatypeIRI(firstNamespace + "one");
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		Literal firstLiteral = VF.createLiteral("first", datatype);
		assertEquals(CoreDatatype.NONE, firstLiteral.getCoreDatatype());
		writer.startQueryResult(ONE_COLUMN);
		writer.handleSolution(new ListBindingSet(ONE_COLUMN, firstLiteral));

		datatype.changeTo(secondNamespace + "two");
		Literal secondLiteral = VF.createLiteral("second", datatype);
		assertEquals(CoreDatatype.NONE, secondLiteral.getCoreDatatype());
		writer.handleSolution(new ListBindingSet(ONE_COLUMN, secondLiteral));
		writer.endQueryResult();
		byte[] expected = expectedStream(ONE_COLUMN, out -> {
			writeNamespace(out, 0, firstNamespace);
			writeTypedLiteral(out, "first", 0, "one");
			writeNamespace(out, 1, secondNamespace);
			writeTypedLiteral(out, "second", 1, "two");
		});

		assertArrayEquals(expected, output.toByteArray());
		assertRoundTrip(output.toByteArray(),
				new ListBindingSet(ONE_COLUMN, VF.createLiteral("first", VF.createIRI(firstNamespace, "one"))),
				new ListBindingSet(ONE_COLUMN, VF.createLiteral("second", VF.createIRI(secondNamespace, "two"))));
	}

